    "review": "首发灾难经多次补丁与DLC「往日之影」后蜕变为优秀都市RPG。夜之城的垂直设计与文化细节至今仍属顶级，任务分支与角色演出极具感染力。2.0更新重做了技能树与警察系统。适合能接受第一人称、重视世界观与演出的玩家；若期待GTA式自由沙盒则会失望。",
