    "title": "FEZ",
    "alt": "FEZ",
    "year": 2012,
    "region": "加拿大",
    "status": "已发售",
    "summary": "Gomez获得红色帽子后能在2D与3D视角间切换，探索立方体碎片修复世界。旋转机制本身就是谜题语言，隐藏层需跳出游戏思维才能解开。",
